import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('el-reconocimiento', 'B',
 [dict(t=1188, e=1232, titulo='El reconocimiento viene del Señor', txt='Y el reconocimiento va a venir, porque el Señor trae galardones. El Señor nos da su honra, su gloria, su honor, pero tiene que venir de parte de él, en el tiempo oportuno. Dios te va a reconocer. A ti y a mí nos van a honrar, pero yo no quiero honra de los hombres, porque eso era lo que decía Jesucristo: «Honra de los hombres yo no recibo». ¿Qué nos quedaría a nosotros si la honra que recibiéramos fuera de los hombres?'),
  dict(t=3527, e=3573, titulo='Los que ya tienen su reconocimiento', txt='Estos oraban; estos de Mateo 6:16 ayunaban. Lo mismo ayunan para que los miren: ya tienen su reconocimiento. Estos le daban a la gente más necesitada, pero hacían promoción. Lo mismo lo daban para ser alabados por los hombres: ya tienen su reconocimiento. Y estos ayudaban a otros, hacían banquete, llamaban a la gente que les podía devolver el favor: «Ah, no, ese yo nunca lo invito a comer, porque él a mí nunca me invita». Y aquí dice que no hagamos eso, porque entonces lo que estamos buscando es que nos paguen el favor que hicimos.'),
  dict(t=4164, e=4199, titulo='Ser agradecido', txt='Ser agradecido es tener uno gratitud en su corazón. Como le dijo una vez un hermano al apóstol: «¿De qué estás agradecido?». «De que ando en bicicleta». «¿Cómo así?». «Sí, porque hago ejercicio, no me molesta cuando sube la gasolina y jamás me detiene el tráfico». Eso es ser agradecido. Pero ¿qué haría otra persona? «Qué desgracia, en sus grandes carros que llegan allí a la iglesia y yo en bicicleta».')],
 [dict(t=1782, txt='Habiendo creído en Dios, recibirás reconocimiento.'),
  dict(t=2355, txt='La honra que queremos es la que viene del Señor.'),
  dict(t=4198, txt='Si tú ofreces gracias a Dios, lo estás honrando, y él te va a honrar a ti.')],
 ['¿De quién has estado esperando el aplauso o el reconocimiento, y qué cambiaría si lo esperaras del Señor «en el tiempo oportuno»?',
  '¿En qué cosas buenas que haces (orar, ayudar, dar) has buscado que te vean, y cómo puedes hacerlas esta semana solo para Dios?',
  'Como el hermano de la bicicleta, ¿qué situación que hoy te molesta puedes mirar con gratitud?'],
 inicio=228)
